            [("Үйде үш бөлме бар.", "үй ішіндегі бөлме саны"), ("Анам ас үйде.", "ананың орны"), ("Кітап үстелде.", "кітаптың орны"), ("Гүл терезеде.", "гүлдің орны"), ("Киім шкафта.", "киімнің орны"), ("Бала мектепте.", "баланың орны")],
