def speech(lang, phrase, meaning):
    return f"[{UI[lang][16]}: {phrase}]({audio_url(phrase)}) — {meaning}"


def render(number, stem, map_stem, lang, data, next_entry):
    ui = UI[lang]
    keys = ("title", "lead", "situation", "phrases", "model", "support", "limit", "predict", "recall", "mistake", "transfer", "project", "task", "repeat")
    d = dict(zip(keys, (data[k] for k in keys)))
    parts = [f"# {d['title']}", "", f"_Lead (summary):_ **{d['lead']}**", "", f"## {ui[0]}", "", MAP_INTRO[lang], "", f"![{d['title']}](/static/course/kazakh-language/map-{map_stem}-{lang}.svg)", "", f"## {ui[1]}", "", d["situation"], "", f"## {ui[2]}", ""]
    for phrase, meaning in d["phrases"]:
        parts += [speech(lang, phrase, meaning), ""]
    sections = [(ui[3], WORKFLOW[lang]), (ui[4], d["model"]), (ui[5], "```kazakh\n" + d["support"] + "\n```"), (ui[6], d["limit"]), (ui[7], d["predict"]), (ui[8], d["recall"]), (ui[9], d["mistake"]), (ui[10], d["transfer"]), (ui[11], d["project"]), (ui[12], d["task"])]
    for heading, body in sections:
        parts += [f"## {heading}", "", body, ""]
    parts += [f"## {ui[13]}", ""] + [f"- {item}" for item in d["repeat"]]
    if next_entry:
        parts += ["", f"[{ui[14]}: {next_entry[2][lang]['title']}](/read/kazakh-language-{next_entry[0]}?lang={lang})"]
    elif stem == "16-people-home-mastery":
        next_titles = {
            "ru": "Школа как карта: места и понятные координаты",
            "kz": "Мектеп карта ретінде: орындар және анық координаттар",
            "en": "School as a map: places and clear coordinates",
        }
        parts += ["", f"[{ui[14]}: {next_titles[lang]}](/read/kazakh-language-17-school-map?lang={lang})"]
    else:
        parts += ["", f"[{ui[15]}](/course/kazakh-language?lang={lang})"]
    return "\n".join(parts).strip() + "\n"


def main():
    OUT.mkdir(parents=True, exist_ok=True)
    if len(LESSONS) != 8:
        raise ValueError("people-home block must contain exactly eight lessons")
    for index, (stem, map_stem, localized) in enumerate(LESSONS):
        next_entry = LESSONS[index + 1] if index + 1 < len(LESSONS) else None
        for lang, data in localized.items():
            suffix = "" if lang == "ru" else f"-{lang}"
            (OUT / f"{stem}{suffix}.md").write_text(render(index + 9, stem, map_stem, lang, data, next_entry), encoding="utf-8")
    print(f"Generated {len(LESSONS) * 3} localized People and Home pages")


if __name__ == "__main__":
    main()
